import math
import sys

class Point:
    def __init__(self, a, b, c, d, e):
        self.v = a
        self.w = b
        self.x = c
        self.y = d
        self.z = e

    def get_magnitude(self):
        return math.sqrt(self.v ** 2 + self.w ** 2 + self.x ** 2 + self.y ** 2 + self.z ** 2)

def is_angle_less_than_90(a, b):
    mag_a = a.get_magnitude()
    mag_b = b.get_magnitude()
    dot = a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z
    # To avoid floating point errors, clip the cosine value
    cosine = dot / (mag_a * mag_b) if mag_a != 0 and mag_b != 0 else 1.0
    cosine = max(min(cosine, 1.0), -1.0)
    angle_deg = math.degrees(math.acos(cosine))
    return angle_deg < 90

def main():
    input_lines = sys.stdin.read().splitlines()
    n = int(input_lines[0])
    if n > 11:
        print(0)
        return
    points = []
    for i in range(1, n + 1):
        parts = list(map(int, input_lines[i].split()))
        points.append(Point(*parts))
    good_indices = set()
    for i in range(n):
        is_good = True
        for j in range(n):
            for k in range(n):
                if i != j and i != k and j != k:
                    p1 = points[j]
                    p2 = points[k]
                    p3 = points[i]
                    v1 = Point(p1.v - p3.v, p1.w - p3.w, p1.x - p3.x, p1.y - p3.y, p1.z - p3.z)
                    v2 = Point(p2.v - p3.v, p2.w - p3.w, p2.x - p3.x, p2.y - p3.y, p2.z - p3.z)
                    if is_angle_less_than_90(v1, v2):
                        is_good = False
        if is_good:
            good_indices.add(i + 1)
    if not good_indices:
        print(0)
    else:
        print(len(good_indices))
        for idx in sorted(good_indices):
            print(idx)

if __name__ == "__main__":
    main()

